// src/app/models/task.model.ts

export type TaskPriority = 'low' | 'medium' | 'high';

export type TaskCategory = 'personal' | 'work' | 'study' | 'development' | 'other';

export interface Task {
  id: string;
  title: string;
  description: string;
  category: TaskCategory;
  priority: TaskPriority;
  dueDate: string | null; // ISO date string (YYYY-MM-DD)
  isCompleted: boolean;
  createdAt: string; // ISO date string
  updatedAt: string; // ISO date string
}

// Payload used when creating a new task (no id, timestamps generated by service)
export type CreateTaskPayload = Omit<Task, 'id' | 'createdAt' | 'updatedAt' | 'isCompleted'> & {
  isCompleted?: boolean;
};

// Payload used when updating a task
export type UpdateTaskPayload = Partial<Omit<Task, 'id' | 'createdAt'>>;

// Add this line at the bottom:
export const TASK_CATEGORIES: TaskCategory[] = ['personal', 'work', 'study', 'development', 'other'];